/**
 * Idempotency for the offline queue.
 *
 * A phone that cannot hear the server has no way to know whether its report arrived. Without a key it must
 * choose between losing the report and risking a second pin; with one, a retry is the same report.
 *
 * The key is generated by the client at compose time (see expo/src/outbox-core.ts) and is opaque to the server.
 * It is validated rather than trusted: an unvalidated key is a way to fill a unique index with junk, and a very
 * long one is a way to waste storage on every retry.
 */

/** Long enough for 128 bits of randomness in base 36, short enough to index comfortably. */
export const CLIENT_KEY_MAX = 72;

// Deliberately narrow: the app generates `m-<base36 time>-<base36 random>`. Anything else is not ours.
const SHAPE = /^[a-z0-9][a-z0-9-]{7,71}$/;

/**
 * A key we are willing to store, or null. Null means "proceed as before" — an old app, a curl, or a caller that
 * simply did not send one. Absence of a key must never be an error, because reporting has to keep working for
 * every client that predates this feature.
 */
export function normaliseClientKey(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const key = value.trim().toLowerCase();
  if (!SHAPE.test(key)) return null;
  return key;
}

/** Postgres "undefined column": the migration has not been run yet. Not a reason to fail a report. */
export function isUndefinedColumn(error: unknown): boolean {
  return (error as { code?: unknown } | null)?.code === "42703";
}

/**
 * A unique-violation on `incidents_client_key_idx`. Postgres reports 23505; both drizzle and pg surface it as
 * `.code`, but a driver may nest it inside `cause`, so both are checked.
 */
export function isUniqueViolation(error: unknown): boolean {
  const code = (e: unknown): string | undefined => {
    if (!e || typeof e !== "object") return undefined;
    const direct = (e as { code?: unknown }).code;
    if (typeof direct === "string") return direct;
    return code((e as { cause?: unknown }).cause);
  };
  return code(error) === "23505";
}
